$this->runAction(function () use ($houseId, $photoId, $caption, $folderId, $sortOrder): DataResponse {
			$uid = $this->requireUid();
			$this->auth->requireMember($houseId, $uid);
			$existing = $this->photos->getPhoto($photoId);
			$this->assertInHouse($existing->getHouseId(), $houseId, 'Photo');
			// Editing needs the role capability or an editor share on the photo
			// (or its containing folder).
			if (!$this->permissions->can($houseId, $uid, 'canUpdatePhotos')
				&& !$this->shares->hasEditShare($uid, Share::TYPE_PHOTO, $photoId)) {
				throw new ForbiddenException('Missing permission: canUpdatePhotos');
			}
			$previousFolderId = $existing->getFolderId();

			$patch = [];
			if ($caption !== null) {
				$patch['caption'] = $caption;
			}
			if ($folderId !== null) {
				// Changing the folder is a move and needs the move capability.
				$normalizedFolderId = $folderId > 0 ? $folderId : null;
				if ($normalizedFolderId !== $previousFolderId
					&& !$this->permissions->isAdmin($houseId, $uid)
					&& !$this->permissions->can($houseId, $uid, 'canMovePhotos')) {
					throw new ForbiddenException('Missing permission: canMovePhotos');
				}
				if ($folderId > 0) {
					$folder = $this->photos->getFolder($folderId);
					$this->assertInHouse($folder->getHouseId(), $houseId, 'Folder');
				}
				$patch['folderId'] = $folderId;
			}
			if ($sortOrder !== null) {
				$patch['sortOrder'] = $sortOrder;
			}
			$photo = $this->photos->updatePhoto($photoId, $patch);

			if ($folderId !== null && $photo->getFolderId() !== $previousFolderId) {
				$this->activity->publishPhotoMoved(
					$houseId,
					$this->houses->get($houseId)->getName(),
					$uid,
					$photoId,
					$photo->getCaption(),
					$previousFolderId,
					$this->safeFolderName($previousFolderId),
					$photo->getFolderId(),
					$this->safeFolderName($photo->getFolderId()),
				);
			}
			$roleEdit = $this->permissions->can($houseId, $uid, 'canUpdatePhotos');
			return new DataResponse($this->photoJson($photo, $roleEdit, $this->shares->userShareMap($houseId, $uid)));
		})

