			$patch = [];
			if ($name !== null) {
				$patch['name'] = $name;
			}
			if ($icon !== null) {
				$patch['icon'] = $icon;
			}
			if ($color !== null) {
				$patch['color'] = $color;
			}
			if ($sortOrder !== null) {
				$patch['sortOrder'] = $sortOrder;
			}
			$patch += $this->collectInfo($brand, $location, $openingHours, $contact, $responsible, $notes);
			$updated = $this->stores->update($storeId, $patch);
			return new DataResponse($updated->jsonSerialize());
